// Random suffixes ("...of the Eagle") an item can roll, with their stats at
// that item's level and quality. Data: data/gear/suffixes.json, generated by
// scripts/build-gear-suffixes.js from the client's bonus tables. Pure and
// erasable TS: callers pass the JSON in (pages import it, build scripts read it).
//
// Stat = round(budget x allocation / 10000). The budget is
// RandPropPoints[itemLevel] for the item's quality, picked by slot group (the
// TBC/retail grouping). The item's own fixed stats ("+8 Attack Power") are not
// included here: they stay on the base tooltip.

import type { StatKey, Stats } from "./item-stats.ts";

export type SuffixData = {
  build: string;
  suffixes: Record<string, { name: string; alloc: [StatKey, number][]; effects: number[] }>;
  trees: Record<string, number[]>;
  items: Record<string, number>;
  budgets: Record<string, Record<"2" | "3" | "4", number[]>>;
};

export type ItemSuffix = { id: number; name: string; stats: Stats; effects: number[] };

// Catalog slot -> budget column: 0 head/chest/legs/two-hand, 1 shoulder/waist/feet/hands/trinket,
// 2 wrist/neck/back/finger/shield/held off-hand, 3 one-hand weapons, 4 ranged.
const SLOT_GROUP: Record<string, number> = {
  Head: 0, Chest: 0, Legs: 0, "Two-Hand": 0,
  Shoulder: 1, Waist: 1, Feet: 1, Hands: 1, Trinket: 1,
  Wrist: 2, Neck: 2, Back: 2, Finger: 2, Shield: 2, "Held In Off-hand": 2,
  "One-Hand": 3, "Main Hand": 3, "Off Hand": 3,
  Ranged: 4, Thrown: 4, Relic: 4,
};

type BaseItem = { itemId: number | null; slot: string | null; quality: number | null; itemLevel: number | null };

// [] when the item can't roll a suffix, or its slot/quality/level has no budget.
export function itemSuffixes(item: BaseItem, data: SuffixData): ItemSuffix[] {
  const tree = item.itemId !== null ? data.items[item.itemId] : undefined;
  const group = item.slot ? SLOT_GROUP[item.slot] : undefined;
  const budget = data.budgets[String(item.itemLevel)]?.[String(item.quality) as "2" | "3" | "4"]?.[group ?? -1];
  if (tree === undefined || budget === undefined) return [];
  return data.trees[tree].map((id) => {
    const s = data.suffixes[id];
    const stats: Stats = {};
    for (const [key, alloc] of s.alloc) stats[key] = (stats[key] ?? 0) + Math.round((budget * alloc) / 10000);
    return { id, name: s.name, stats, effects: s.effects };
  });
}
